import math
from functools import reduce

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def count_cycles(m_prime, multiplier):
    """
    Calculates the number of cycles of the permutation x -> multiplier*x mod m_prime 
    acting on Z_m_prime^*.
    """
    if m_prime == 1:
        return 0

    S_prime = [a for a in range(1, m_prime) if gcd(a, m_prime) == 1]
    visited = set()
    cycle_count = 0

    for start_node in S_prime:
        if start_node not in visited:
            cycle_count += 1
            current = start_node
            while current not in visited:
                visited.add(current)
                current = (multiplier * current) % m_prime
                if current == 0: # Should not happen if gcd(multiplier, m_prime) = 1, but good to check
                    break
    return cycle_count

def calculate_C_m(m):
    """
    Calculates the total number of cycles C(m) for x -> 3x mod m on {1, ..., m-1}.
    """
    if m == 1:
        return 0

    divisors = get_divisors(m)
    total_cycles = 0

    # m' runs over divisors of m such that m' > 1
    for m_prime in divisors:
        if m_prime > 1:
            # We need N(m', 3)
            total_cycles += count_cycles(m_prime, 3)

    return total_cycles

# Test for m up to 30 such that 3 does not divide m
results = {}
for m in range(1, 31):
    if m % 3 != 0:
        C_m = calculate_C_m(m)
        is_odd = "Odd" if C_m % 2 != 0 else "Even"
        results[m] = (C_m, is_odd)

print("m, C(m), Is_Odd")
for m, (C_m, is_odd) in results.items():
    print(f"{m}, {C_m}, {is_odd}")

